-- ARC · Luna como su propia asesorada, con su plan semanal (PLAN_LUNA_ARC_WORKOUT)
-- Pégalo en Supabase > SQL Editor > Run. Usa tu cuenta de coach (la que tiene role = 'coach').
-- Si lo vuelves a pegar, actualiza la rutina en vez de duplicarte.
insert into public.coach_clients (coach_id, email, name, client_id, routine)
select p.id, lower(u.email), 'Luna (yo)', p.id, $arc$[{"name": "Pierna glúteo", "ex": [{"id": "ARC-060", "sets": 3, "reps": "12–20", "rir": 1, "rest": 90}, {"id": "ARC-054", "sets": 3, "reps": "1×6–8 / 2×8–12", "rir": 1, "rest": 165}, {"id": "ARC-X01", "sets": 3, "reps": "8–12 por pierna", "rir": 1, "rest": 120}, {"id": "ARC-049", "sets": 3, "reps": "10–15", "rir": 1, "rest": 105}, {"id": "ARC-X03", "sets": 3, "reps": "12–15 por pierna", "rir": 1, "rest": 60}, {"id": "ARC-041", "sets": 3, "reps": "10–15", "rir": 1, "rest": 90}]}, {"name": "Jalón y abdomen", "ex": [{"id": "ARC-007", "sets": 3, "reps": "máx. (opcional)", "rir": 1, "rest": 120}, {"id": "ARC-009", "sets": 3, "reps": "1×6–8 / 2×8–12", "rir": 1, "rest": 150}, {"id": "ARC-014", "sets": 3, "reps": "8–12", "rir": 1, "rest": 120}, {"id": "ARC-015", "sets": 3, "reps": "10–12 por brazo", "rir": 1, "rest": 105}, {"id": "ARC-020", "sets": 3, "reps": "12–15", "rir": 1, "rest": 90}, {"id": "ARC-019", "sets": 3, "reps": "12–15", "rir": 1, "rest": 60}, {"id": "ARC-029", "sets": 3, "reps": "10–12", "rir": 1, "rest": 90}, {"id": "ARC-081", "sets": 3, "reps": "10–15", "rir": 1, "rest": 90}]}, {"name": "Comba y core", "ex": [{"id": "CARDIO", "sets": 1, "reps": "30", "rir": 0, "rest": 60}, {"id": "ARC-067", "sets": 3, "reps": "8–15", "rir": 1, "rest": 90}, {"id": "ARC-081", "sets": 3, "reps": "10–15", "rir": 1, "rest": 90}, {"id": "ARC-079", "sets": 3, "reps": "6–12", "rir": 1, "rest": 90}]}, {"name": "Pierna cuádriceps", "ex": [{"id": "ARC-076", "sets": 3, "reps": "1×6–8 / 2×8–12", "rir": 1, "rest": 165}, {"id": "ARC-075", "sets": 3, "reps": "8–12", "rir": 1, "rest": 120}, {"id": "ARC-072", "sets": 3, "reps": "8–10", "rir": 2, "rest": 150}, {"id": "ARC-050", "sets": 3, "reps": "10–15", "rir": 1, "rest": 90}, {"id": "ARC-041", "sets": 3, "reps": "10–15", "rir": 1, "rest": 90}, {"id": "ARC-060", "sets": 2, "reps": "15–20", "rir": 1, "rest": 60}]}, {"name": "Empujes", "ex": [{"id": "ARC-023", "sets": 3, "reps": "1×6–8 / 2×8–12", "rir": 1, "rest": 150}, {"id": "ARC-022", "sets": 3, "reps": "8–12 (superserie con el siguiente)", "rir": 1, "rest": 15}, {"id": "ARC-036", "sets": 3, "reps": "10–12", "rir": 1, "rest": 120}, {"id": "ARC-087", "sets": 3, "reps": "10–15", "rir": 1, "rest": 90}, {"id": "ARC-027", "sets": 3, "reps": "12–15 por brazo", "rir": 1, "rest": 90}, {"id": "ARC-026", "sets": 2, "reps": "15–20 + parciales", "rir": 0, "rest": 60}, {"id": "ARC-019", "sets": 3, "reps": "12–15", "rir": 1, "rest": 90}, {"id": "ARC-004", "sets": 2, "reps": "8–12 (opcional)", "rir": 1, "rest": 120}]}, {"name": "Calistenia y abdomen", "ex": [{"id": "ARC-007", "sets": 4, "reps": "5–8", "rir": 1, "rest": 120}, {"id": "ARC-006", "sets": 3, "reps": "6–10", "rir": 1, "rest": 120}, {"id": "ARC-001", "sets": 3, "reps": "8–15", "rir": 1, "rest": 90}, {"id": "ARC-067", "sets": 3, "reps": "8–12", "rir": 1, "rest": 90}, {"id": "ARC-081", "sets": 3, "reps": "10–15", "rir": 1, "rest": 90}, {"id": "ARC-079", "sets": 3, "reps": "6–12", "rir": 1, "rest": 90}]}]$arc$::jsonb
from public.profiles p join auth.users u on u.id = p.id
where p.role = 'coach'
order by p.created_at nulls last
limit 1
on conflict (coach_id, email) do update set routine = excluded.routine, name = excluded.name, client_id = excluded.client_id, updated_at = now();

-- Comprobación: debería salir 1 fila con 6 días
select name, email, jsonb_array_length(routine) as dias from public.coach_clients where name = 'Luna (yo)';
